<template>
  <v-card
      class="mx-auto cursor-pointer text-center"
      width="350"
  >
    <ProductList></ProductList>
    <v-card-actions class="justify-center mt-3 pb-4">
      <v-btn
          text="Pay"
          variant="flat"
          :color="colors.primary"
          @click="checkout = true"
      >
      </v-btn>
    </v-card-actions>
  </v-card>
  <v-dialog v-model="checkout" max-width="600px" width="auto">
    <v-card
        max-width="500"
        height="700"
        prepend-icon="mdi-cash-sync"
        title="Pay process"
    >
      <v-btn size="small" class="position-absolute right-0" variant="plain" icon @click="checkout = false">
        <v-icon>mdi-close</v-icon>
      </v-btn>
      <EmbedWidget :checkoutOptions="checkoutOptions" style="overflow-x: hidden; overflow-y: scroll"
                   :amount="amount"></EmbedWidget>
    </v-card>
  </v-dialog>
</template>

<script>
import colors from "@/utils/colors.js";
import params from "@/utils/params.js";
import ProductList from "@/components/products/ProductList.vue";
import EmbedWidget from "@/components/widgets/Embed.vue";
import cloneDeep from "lodash/cloneDeep";

export default {
  name: "CheckoutJsWidget",
  components: {EmbedWidget, ProductList},
  props: {
    amount: 0,
    activatorProps: null,
    checkoutOptions: {
      type: Object,
      default: () => cloneDeep(params)
    }
  },
  beforeMount() {
    this.checkoutOptions.options.subscription = {
      type: "shown_edit_on",
      periods: ["week", "month", "day"]
    }
    this.checkoutOptions.params.recurring_data = {
      every: 1,
      amount: this.amount * 100,
      period: "month",
      end_time: "2035-11-14"
    }
    this.checkoutOptions.css_variable = {
      main: "#FF558A",
    }
  },
  data() {
    return {
      colors: colors,
      checkout: false,
    };
  },
};
</script>