import { createNamespacedHelpers as nameSpace } from "vuex";

const {
	mapActions: cartActions,
} = nameSpace("cartModule");

export default {
    name: "CheckoutMixins",

    methods: {
        ...cartActions([
          "clearCartVuex",
          "setView"
        ]),
        paymentApproved() {
            this.$router.push('/payment');
        },
        clearCart(){
            this.clearCartVuex();
            this.setView(false);
        }
    },
};